create table public.customer_appointment_requests(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),customer_id uuid not null references public.customers(id),auth_user_id uuid not null,pet_id uuid not null references public.pets(id),service_id uuid not null references public.services(id),preferred_date date not null,preferred_period text not null check(preferred_period in('manha','tarde')),notes text,status text not null default'pendente'check(status in('pendente','aprovada','recusada','cancelada')),created_at timestamptz not null default now());create index portal_requests_user_idx on public.customer_appointment_requests(auth_user_id,created_at desc);create index portal_requests_company_idx on public.customer_appointment_requests(company_id);
alter table public.customer_appointment_requests enable row level security;create policy portal_requests_self_select on public.customer_appointment_requests for select to authenticated using(auth_user_id=(select auth.uid()));create policy portal_requests_staff_select on public.customer_appointment_requests for select to authenticated using((select private.is_company_member(company_id)));create policy portal_requests_staff_update on public.customer_appointment_requests for update to authenticated using((select private.has_company_role(company_id,array['proprietario','administrador','gerente','atendente'])))with check((select private.has_company_role(company_id,array['proprietario','administrador','gerente','atendente'])));revoke all on public.customer_appointment_requests from public,anon,authenticated;grant select,update on public.customer_appointment_requests to authenticated;
create function private.portal_customer()returns public.customers language plpgsql security definer set search_path=''as $$declare r public.customers;u uuid:=(select auth.uid());e text;begin select email into e from auth.users where id=u and email_confirmed_at is not null;if e is null then raise exception'Confirme seu e-mail';end if;select*into strict r from public.customers where is_active and lower(email)=lower(e);return r;exception when no_data_found then raise exception'Nenhum cliente vinculado a este e-mail';when too_many_rows then raise exception'E-mail vinculado a mais de uma empresa';end$$;
create function private.portal_data()returns jsonb language plpgsql security definer set search_path=''as $$declare c public.customers;begin c:=private.portal_customer();return jsonb_build_object('customer',to_jsonb(c),'company',(select to_jsonb(x)from public.companies x where id=c.company_id),'pets',coalesce((select jsonb_agg(to_jsonb(x))from public.pets x where customer_id=c.id and company_id=c.company_id),'[]'),'appointments',coalesce((select jsonb_agg(to_jsonb(x)order by scheduled_at desc)from public.appointments x where customer_id=c.id and company_id=c.company_id),'[]'),'packages',coalesce((select jsonb_agg(to_jsonb(x))from public.customer_packages x where customer_id=c.id and company_id=c.company_id),'[]'),'services',coalesce((select jsonb_agg(to_jsonb(x))from public.services x where company_id=c.company_id and is_active),'[]'),'requests',coalesce((select jsonb_agg(to_jsonb(x)order by created_at desc)from public.customer_appointment_requests x where auth_user_id=(select auth.uid())),'[]'));end$$;
create function private.portal_request(p_pet uuid,p_service uuid,p_date date,p_period text,p_notes text)returns uuid language plpgsql security definer set search_path=''as $$declare c public.customers;r uuid;begin c:=private.portal_customer();if p_date<current_date or p_period not in('manha','tarde')or not exists(select 1 from public.pets where id=p_pet and customer_id=c.id)or not exists(select 1 from public.services where id=p_service and company_id=c.company_id and is_active)then raise exception'Dados inválidos';end if;insert into public.customer_appointment_requests(company_id,customer_id,auth_user_id,pet_id,service_id,preferred_date,preferred_period,notes)values(c.company_id,c.id,(select auth.uid()),p_pet,p_service,p_date,p_period,p_notes)returning id into r;return r;end$$;
create function public.get_customer_portal()returns jsonb language sql security invoker set search_path=''as $$select private.portal_data()$$;create function public.request_customer_appointment(p_pet uuid,p_service uuid,p_date date,p_period text,p_notes text default null)returns uuid language sql security invoker set search_path=''as $$select private.portal_request(p_pet,p_service,p_date,p_period,p_notes)$$;
revoke all on function private.portal_customer(),private.portal_data(),private.portal_request(uuid,uuid,date,text,text)from public,anon;grant execute on function private.portal_customer(),private.portal_data(),private.portal_request(uuid,uuid,date,text,text)to authenticated;revoke all on function public.get_customer_portal(),public.request_customer_appointment(uuid,uuid,date,text,text)from public,anon;grant execute on function public.get_customer_portal(),public.request_customer_appointment(uuid,uuid,date,text,text)to authenticated;
